package org.eclipse.rdf4j.sail.lmdb;

import static org.eclipse.rdf4j.sail.lmdb.CanonicalIriCompatibilityProcess.CURRENT_IRI;
import static org.eclipse.rdf4j.sail.lmdb.CanonicalIriCompatibilityProcess.CURRENT_SUBJECT;
import static org.eclipse.rdf4j.sail.lmdb.CanonicalIriCompatibilityProcess.OLD_IRI;
import static org.eclipse.rdf4j.sail.lmdb.CanonicalIriCompatibilityProcess.OLD_SUBJECT;
import static org.eclipse.rdf4j.sail.lmdb.CanonicalIriCompatibilityProcess.PREDICATE;
import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.junit.jupiter.api.Assumptions.assumeTrue;

import java.nio.file.Files;
import java.nio.file.Path;
import java.util.List;
import java.util.Properties;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.repository.RepositoryConnection;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;

/**
 * Actual 6.1.0 assets, not newly created stores relabeled with an old version. The two process tests additionally run
 * the original release when scripts/verify-canonical-iri-compatibility.sh supplies its independently compiled
 * classpath.
 */
class LmdbCanonicalIriCompatibilityTest {

	static final String RELEASE_610_COMMIT = "46a2d41ab16fead609884ee655e26e6baa1ce325";
	private static final String CLASSPATH_PROPERTY = "rdf4j.lmdb.canonical.compat.classpath.format2";

	@Test
	void authenticReleaseFixtureRetainsIdsSplitsAndPropertiesAcrossReadWriteReopen(
			@TempDir Path temporaryDirectory) throws Exception {
		Path directory = extract(temporaryDirectory);
		Properties metadata = CanonicalIriCompatibilityProcess.load(temporaryDirectory.resolve("manifest.properties"));
		assertEquals(RELEASE_610_COMMIT, metadata.getProperty("producer.commit"));
		assertEquals("2", metadata.getProperty("store.version"));
		assertEquals("false", metadata.getProperty("inline-literals"));
		assertTrue(metadata.getProperty("producer.value-store.sha256").matches("[0-9a-f]{64}"));
		byte[] originalProperties = Files.readAllBytes(directory.resolve("store.properties"));
		writeWithCurrent(directory, metadata);
		SailRepository repository = CanonicalIriCompatibilityProcess.repository(directory, false);
		repository.init();
		try {
			CanonicalIriCompatibilityProcess.verify(repository, metadata);
			try (RepositoryConnection connection = repository.getConnection()) {
				assertTrue(connection.hasStatement(CURRENT_SUBJECT, PREDICATE, CURRENT_IRI, false));
			}
		} finally {
			repository.shutDown();
		}
		assertArrayEquals(originalProperties, Files.readAllBytes(directory.resolve("store.properties")),
				"Opening/writing an old generation must not rewrite its persisted policy");
	}

	@Test
	void originalReleaseReopensCurrentWritesAndClearWithoutAnyUpgrade(@TempDir Path temporaryDirectory)
			throws Exception {
		String classpath = System.getProperty(CLASSPATH_PROPERTY);
		assumeTrue(classpath != null && !classpath.isBlank(), "Run the pinned-binary compatibility script");
		Path directory = extract(temporaryDirectory);
		Path manifest = temporaryDirectory.resolve("manifest.properties");
		Properties metadata = CanonicalIriCompatibilityProcess.load(manifest);
		byte[] originalProperties = Files.readAllBytes(directory.resolve("store.properties"));
		writeWithCurrent(directory, metadata);
		runOriginal(classpath, "verify-current-and-write", directory, manifest);
		SailRepository repository = CanonicalIriCompatibilityProcess.repository(directory, false);
		repository.init();
		try {
			CanonicalIriCompatibilityProcess.verify(repository, metadata);
			try (RepositoryConnection connection = repository.getConnection()) {
				assertTrue(connection.hasStatement(OLD_SUBJECT, PREDICATE, OLD_IRI, false));
				connection.begin();
				connection.clear();
				connection.add(CURRENT_SUBJECT, PREDICATE, CURRENT_IRI);
				connection.commit();
			}
		} finally {
			repository.shutDown();
		}
		runOriginal(classpath, "verify-cleared-current-and-write", directory, manifest);
		repository = CanonicalIriCompatibilityProcess.repository(directory, false);
		repository.init();
		try (RepositoryConnection connection = repository.getConnection()) {
			assertEquals(2, connection.size());
			assertTrue(connection.hasStatement(CURRENT_SUBJECT, PREDICATE, CURRENT_IRI, false));
			assertTrue(connection.hasStatement(OLD_SUBJECT, PREDICATE, OLD_IRI, false));
		} finally {
			repository.shutDown();
		}
		assertArrayEquals(originalProperties, Files.readAllBytes(directory.resolve("store.properties")));
	}

	@Test
	void originalReleaseRejectsNewAndInterruptedCanonicalStoresWithoutModifyingThem(
			@TempDir Path temporaryDirectory) throws Exception {
		String classpath = System.getProperty(CLASSPATH_PROPERTY);
		assumeTrue(classpath != null && !classpath.isBlank(), "Run the pinned-binary compatibility script");
		for (boolean interrupted : List.of(false, true)) {
			Path directory = temporaryDirectory.resolve(interrupted ? "interrupted" : "completed");
			SailRepository repository = CanonicalIriCompatibilityProcess.repository(directory, true);
			repository.init();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.add(CURRENT_SUBJECT, PREDICATE, CURRENT_IRI);
			} finally {
				repository.shutDown();
			}
			assertEquals("7", CanonicalIriCompatibilityProcess.load(directory.resolve("store.properties"))
					.getProperty("version"));
			if (interrupted) {
				// The distinct marker also protects interrupted canonical generations from historical startup paths.
				Files.createFile(directory.resolve(".lmdb-initial-import-v7.incomplete"));
			}
			var before = LmdbCompatibilityFixtures.snapshot(directory);
			runOriginal(classpath, "reject", directory, temporaryDirectory.resolve("unused.properties"));
			assertEquals(before, LmdbCompatibilityFixtures.snapshot(directory),
					"Rejected old readers must leave every persistent file byte-for-byte unchanged");
		}
	}

	private static Path extract(Path directory) throws Exception {
		LmdbCompatibilityFixtures.extract("canonical-iri-format-2.zip", directory);
		return directory.resolve("store");
	}

	private static void writeWithCurrent(Path directory, Properties metadata) throws Exception {
		SailRepository repository = CanonicalIriCompatibilityProcess.repository(directory, false);
		repository.init();
		try {
			CanonicalIriCompatibilityProcess.verify(repository, metadata);
			ValueStore dictionary = CanonicalIriCompatibilityProcess.dictionary(repository);
			List<Value> values = CanonicalIriCompatibilityProcess.values();
			dictionary.clearCaches();
			dictionary.startTransaction(true);
			for (int index = 0; index < values.size(); index++) {
				Value value = values.get(index);
				long expectedId = Long.parseLong(metadata.getProperty("value." + index + ".id"));
				assertEquals(expectedId, dictionary.storeValue(value), "original split " + index);
				if (value instanceof IRI iri) {
					dictionary.clearCaches();
					IRI canonical = SimpleValueFactory.getInstance().createIRI(iri.stringValue());
					assertEquals(expectedId, dictionary.getId(canonical), "canonical lookup of old split " + index);
					assertEquals(expectedId, dictionary.storeValue(canonical), "canonical reinsertion " + index);
				}
			}
			dictionary.commit();
			try (RepositoryConnection connection = repository.getConnection()) {
				connection.begin();
				connection.add(CURRENT_SUBJECT, PREDICATE, CURRENT_IRI);
				connection.commit();
			}
		} finally {
			repository.shutDown();
		}
	}

	private static void runOriginal(String classpath, String action, Path directory, Path manifest) throws Exception {
		Path output = Files.createTempFile(directory.getParent(), "original-" + action + "-", ".log");
		Process process = new ProcessBuilder(Path.of(System.getProperty("java.home"), "bin", "java").toString(),
				"-ea", "-cp", classpath, CanonicalIriCompatibilityProcess.class.getName(), action,
				directory.toString(), manifest.toString()).redirectErrorStream(true)
						.redirectOutput(output.toFile())
						.start();
		try {
			assertTrue(process.waitFor(60, TimeUnit.SECONDS), "Pinned binary process did not finish: " + output);
			assertEquals(0, process.exitValue(), () -> readOutput(output));
		} finally {
			if (process.isAlive()) {
				process.destroyForcibly();
			}
		}
	}

	private static String readOutput(Path path) {
		try {
			return Files.readString(path);
		} catch (Exception failure) {
			return "Unable to read pinned binary log " + path + ": " + failure;
		}
	}
}
